/* GPS L1 C/A lecture: consistent academic content and explicit analog/digital states. */
(function(){
'use strict';
const $=id=>document.getElementById(id),esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors=['#72d8ef','#8cb6ee','#6ce0bc','#a9d991','#ffd17a','#ff9c86','#f39ad1','#bea6ff','#89b5ff','#c4de8a'];
const curriculum=[
 {title:'Electromagnetic Spectrum and GPS L1 C/A',short:'Spectrum and GPS L1 C/A',definition:'GPS L1 C/A is a coded radio signal at 1575.42 MHz that carries a ranging code and navigation data.',focus:'Locate GPS L1 in the electromagnetic spectrum, then distinguish its carrier, ranging code and navigation message.',explanation:'The carrier is a repeating electromagnetic oscillation. The C/A code changes its phase in a known pattern at 1.023 million chips per second. A chip is one element of that code. Navigation data changes at 50 bits per second and describes the satellite orbit and clock. Together these components allow a receiver to identify a satellite and measure signal travel time.'},
 {title:'GNSS Receiver Architecture',short:'Received Signal and Architecture',focus:'Follow the received analog voltage through conditioning to the digital IF output.'},
 {title:'Antenna Reception and Polarization',short:'Antenna Reception',focus:'Explain how an incoming electromagnetic field becomes a weak analog voltage.'},
 {title:'RF Filtering and Bandwidth',short:'RF Filtering',focus:'Separate carrier frequency, signal bandwidth and the filter passband.'},
 {title:'Amplification, Power Levels and Noise',short:'Amplification and Noise',example:'With an antenna-level input of -130 dBm and 20 dB gain, the output level is -110 dBm. This is a power increase by a factor of 100, or a voltage increase by a factor of 10 at unchanged impedance. A noise figure of 3 dB means the amplifier degrades SNR by 3 dB; gain alone does not improve SNR.',focus:'Learn power, gain, dB and dBm, then distinguish signal amplification from improved signal quality.'},
 {title:'Downconversion: Mixer, Local Oscillator and IF Filter',short:'Downconversion',definition:'Downconversion moves a signal to a lower carrier frequency while preserving its modulation, then selects the required mixer product.',focus:'Treat the mixer, local oscillator and first IF filter as one frequency-downconversion stage.',explanation:'The mixer multiplies the received RF voltage by a locally generated sinusoid. Multiplication produces sum and difference frequencies. The first IF filter selects the difference-frequency band at 47.74 MHz and rejects the unwanted sum-frequency band. The C/A code, navigation data and received Doppler remain carried by the selected signal.'},
 {title:'IF Amplification and Anti-Alias Filtering',short:'IF Conditioning',definition:'IF conditioning amplifies the selected intermediate-frequency signal and limits its bandwidth before sampling.',focus:'Continue from the first IF filter through the 50 dB amplifier and final 6 MHz filter.',explanation:'The downconversion stage has already selected the 47.74 MHz IF with an 18 MHz filter. The IF amplifier increases its voltage. The final IF filter narrows the passband to approximately 6 MHz, reducing out-of-band energy before the ADC. This band limiting helps prevent unwanted spectral components from overlapping the desired signal after sampling.'},
 {title:'Sampling, Aliasing and Quantization',short:'Sampling and Aliasing',definition:'An ADC samples an analog voltage at discrete times and represents each measurement with a finite numerical level.',focus:'Distinguish time sampling, frequency aliasing and amplitude quantization.'},
 {title:'Digital IF and Sample Representation',short:'Digital IF Samples',focus:'Read time, amplitude and frequency views of the same digital sample sequence.'},
 {title:'Raw I/Q Files and Sample Formats',short:'Raw I/Q Files',definition:'A raw I/Q file stores paired in-phase and quadrature sample values, with the format and sampling rate specified separately.',focus:'Inspect quadrature representation, file layout, sample counts and phase preservation.',explanation:'The reference output is real digital IF. A further digital frequency conversion can form complex baseband I/Q. A raw file stores those numerical values in a defined order; reading it requires the sampling rate, data type and I/Q convention.'}
];
const activities=[
 {title:'Carrier phase and code modulation',control:'fe-carrier-phase',change:'Move the carrier-phase slider.',observe:'Watch the carrier shift while the code preserves its 180-degree sign reversals.'},
 {title:'One observed GPS signal at the receiver',control:'fe-rx-noise',change:'Switch modeled noise on and off, or choose another observed GPS satellite.',observe:'Compare the received waveform, I/Q distribution and spectrum for the same epoch.'},
 {title:'RHCP and LHCP antenna polarization',control:'fe-pol-phase',change:'Move the phase slider, reverse the viewing direction, or change antenna handedness.',observe:'Follow field rotation and compare ideal polarization coupling.'},
 {title:'RF bandwidth and frequency selection',control:'fe-filter-rf-bandwidth',change:'Select a narrower or wider experimental RF bandwidth.',observe:'Watch which frequencies are attenuated in the before/after spectrum and voltage.'},
 {title:'Amplifier gain and signal amplitude',control:'fe-amplifier-gain',change:'Increase or decrease the experimental amplifier gain.',observe:'Compare voltage amplitude and the calculated output power; signal and existing noise rise together.'},
 {title:'Local oscillator and downconversion',control:'fe-lo-frequency',change:'Change the local-oscillator frequency, then reset the reference.',observe:'Watch the translated C/A main lobe move into or out of the nominal IF passband.'},
 {title:'First and final IF filtering',control:'fe-filter-choice',change:'Switch between the first and final IF filters.',observe:'Compare their passbands using matched before/after signals with amplifier gain kept separate.'},
 {title:'Sampling and spectral aliasing',control:'fe-alias-rate',change:'Choose a different sampling frequency.',observe:'Watch the sampled frequency mapping and see when the full IF band overlaps itself.'},
 {title:'ADC range utilization and clipping',control:'adc-gain',change:'Move the ADC input-gain slider.',observe:'Compare the sample waveform, quantization histogram and spectrum as clipping develops.'},
 {title:'Phase preservation in raw I/Q',control:'phase',change:'Sweep the phase through 90, 180 and 270 degrees.',observe:'Compare the single I projection with the I/Q phasor and recovered phase.'}
];
function activityGuide(index){const a=activities[index];return `<section class="fe-activity-guide" aria-label="Interactive visual explanation"><div><span class="eyebrow">INTERACTIVE VISUAL EXPLANATION</span><h3>${a.title}</h3><p><strong>Change:</strong> ${a.change}</p><p><strong>Observe:</strong> ${a.observe}</p></div><a href="#fe-experiment" data-start-experiment>Start experiment &#8595;</a></section>`;}
function bindActivity(index){
 const a=activities[index],control=$(a.control),card=control?.closest('.fe-card');if(!card)return;
 card.dataset.interactiveConcept=a.title;
 const marker=document.createElement('span');marker.id='fe-experiment';marker.className='fe-experiment-anchor';marker.setAttribute('aria-hidden','true');card.before(marker);
 document.querySelectorAll('[href="#fe-experiment"]').forEach(link=>link.onclick=event=>{event.preventDefault();for(let node=card.parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;const group=control.closest('.fe-controls,.fe-rx-controls,.fe-pol-controls,.fe-filter-controls,.fe-alias-control')||control;group.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});control.focus({preventScroll:true});});
}
const shortTitles=curriculum.map(section=>section.short);
const stageDesign=shortTitles.map((title,i)=>({title,color:colors[i]}));
const state={lesson:0,epoch:0,satellite:null,scene:[],path:null,revision:0,meta:null,source:'individual',receivedView:'individual',gain:1,carrierPhase:0,experimentGain:20,includeNoise:true};
const spectra=new WeakMap();
const card=(title,body)=>`<section class="card fe-card"><div class="card-head"><h3>${title}</h3></div>${body}</section>`;
const prose=s=>`<div class="fe-prose"><p>${FE_CONCEPTS.html(s)}</p></div>`;

function plot(id,traces,xTitle,yTitle,extra={}){
 const node=$(id);if(!node)return;
 const layout={paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{family:getComputedStyle(document.body).fontFamily,color:'#d7e8f0',size:13},margin:{l:66,r:20,t:52,b:66},xaxis:{title:{text:xTitle},gridcolor:'#294758',automargin:true},yaxis:{title:{text:yTitle},gridcolor:'#294758',automargin:true},legend:{orientation:'h',y:1.18},autosize:true,...extra};
 if(id==='phase-circle')Object.assign(layout.yaxis,{scaleanchor:'x',scaleratio:1});
 FE_CHARTS.draw(node,traces,layout,{responsive:true,displaylogo:false});
}
function trace(x,y,name,color=colors[state.lesson]){return {x,y,name,type:'scatter',mode:'lines',line:{color,width:1.4}};}
function drawArchitectureConnections(){
 document.querySelectorAll('.fe-reference-node').forEach(node=>{if(node.querySelector('.fe-node-hit'))return;const b=node.getBBox(),hit=document.createElementNS('http://www.w3.org/2000/svg','rect');hit.setAttribute('class','fe-node-hit');hit.setAttribute('x',b.x-5);hit.setAttribute('y',b.y-5);hit.setAttribute('width',b.width+10);hit.setAttribute('height',b.height+10);hit.setAttribute('rx','10');hit.setAttribute('fill',node.classList.contains('is-current')?colors[state.lesson]:'transparent');hit.setAttribute('fill-opacity',node.classList.contains('is-current')?'.13':'0');hit.setAttribute('stroke',node.classList.contains('is-current')?colors[state.lesson]:'none');hit.setAttribute('stroke-width','1.5');hit.style.pointerEvents='all';node.prepend(hit);});
}
function architecture(){
 const text=(x,y,t,size=15,color='#dce9f5')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${color}" stroke="none" font-size="${size}">${t}</text>`;
 const filter=(x)=>`<rect x="${x-37}" y="205" width="74" height="60" rx="6"/><path d="M${x-24} 222q8 -10 16 0t16 0t16 0M${x-24} 235q8 -10 16 0t16 0t16 0M${x-24} 248q8 -10 16 0t16 0t16 0"/>`;
 const active=section=>(state.lesson===5&&(section===5))||(state.lesson===6&&section===6)||state.lesson===section||state.lesson===1||state.lesson===9||(state.lesson===0&&section===2);
 const locations=['Received GPS L1 C/A signal at the antenna input','Complete receiver architecture','Receiving antenna','RF bandpass filter','RF amplifier','Downconversion: mixer, local oscillator and first IF filter','IF amplifier and final anti-alias filter','ADC and sampling-clock input','Sampled digital IF output','Complete RF-to-digital signal transformation'];
 const node=(section,title,body)=>`<a href="#front-end-main" data-chain-section="${section}" aria-label="${title}" ${active(section)?'aria-current="step"':''} class="fe-reference-node ${active(section)?'is-current':''}"><title>${title}</title>${body}</a>`;
 const arrow=(d,clock=false)=>`<path d="${d}" fill="none" stroke="${clock?'#ffd17a':'#72d8ef'}" stroke-width="3" marker-end="url(#${clock?'reference-clock':'reference-rf'})"/>`;
 return `<div class="fe-location" role="status"><span class="fe-location-badge">YOU ARE HERE</span><div><strong>${curriculum[state.lesson].title}</strong><p>${locations[state.lesson]}</p></div></div><div class="fe-system-heading"><div><span class="eyebrow">REFERENCE RECEIVER ARCHITECTURE</span><h3>GPS L1 C/A Receiver: RF Front End</h3><p>Cyan traces carry the received signal. Gold traces supply the local oscillator and sampling clock.</p></div><a class="fe-simulation-link" href="/signals/#received">GNSS Signal Simulation &#8599;<small>Continue with the same satellite and epoch</small></a></div><div class="fe-reference-scroll" tabindex="0" role="region" aria-label="Receiver circuit diagram; scroll horizontally on small screens"><svg class="fe-reference-svg" viewBox="0 0 1400 650" role="img" aria-labelledby="reference-title reference-description"><title id="reference-title">Reference GPS L1 C/A receiver circuit</title><desc id="reference-description">Antenna, RF filter, amplifier, mixer, IF filter, IF amplifier, final IF filter, ADC, sampled IF. The 10 MHz reference drives a 1527.68 MHz synthesizer. Its output branches directly to the mixer and through a divide-by-40 circuit to the ADC clock.</desc><defs><marker id="reference-rf" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#72d8ef"/></marker><marker id="reference-clock" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#ffd17a"/></marker></defs><rect x="12" y="15" width="1376" height="385" rx="12" fill="#0c1c2d" stroke="#37647a"/><rect x="12" y="426" width="1376" height="207" rx="12" fill="#0c1c2d" stroke="#827047"/>${text(170,48,'RF SIGNAL PATH',18,'#72d8ef')}${text(300,458,'FREQUENCY SYNTHESIS AND SAMPLING CLOCK',18,'#ffd17a')}<rect x="535" y="145" width="245" height="215" rx="12" fill="#ff9c86" fill-opacity=".05" stroke="#8b655b" stroke-dasharray="5 5"/>${text(657,132,'DOWNCONVERSION',13,'#ffb09d')}<g fill="none" stroke="#72d8ef" stroke-width="3">
 ${node(2,'Receiving antenna',`<path d="M50 100H90L70 135ZM70 100V235"/>${text(180,110,'Active antenna')}`)}
 ${node(3,'RF bandpass filter',filter(280)+text(280,294,'RF bandpass filter')+text(280,318,'1575.42 MHz',14)+text(280,341,'Minimum BW: 2.046 MHz',13))}
 ${node(4,'RF amplifier',`<path d="M435 205L490 235L435 265Z"/>${text(460,185,'Amplifier')}`)}
 ${node(5,'Mixer',`<circle cx="580" cy="235" r="27"/><path d="M564 219L596 251M596 219L564 251"/>${text(580,185,'Mixer')}`)}
 ${node(5,'First IF filter',filter(715)+text(715,294,'IF bandpass filter')+text(715,318,'47.74 MHz',14)+text(715,341,'Minimum BW: 2.046 MHz',13))}
 ${node(6,'IF amplifier',`<path d="M850 205L905 235L850 265Z"/>${text(875,165,'Amplifier')}${text(875,185,'50 dB gain',13)}`)}
 ${node(6,'Final IF filter',filter(1030)+text(1030,294,'Final IF filter')+text(1030,318,'47.74 MHz',14)+text(1030,341,'Minimum BW: 2.046 MHz',13))}
 ${node(7,'Analog-to-digital converter',`<rect x="1180" y="205" width="85" height="60" rx="6"/>${text(1222,243,'ADC',23)}${text(1222,134,'Analog-to-digital converter')}${text(1222,158,'38.192 Msamples/s',14)}${text(1222,181,'4-bit samples',14)}`)}
 </g>${arrow('M70 235H243')}${arrow('M317 235H435')}${arrow('M490 235H553')}${arrow('M607 235H678')}${arrow('M752 235H850')}${arrow('M905 235H993')}${arrow('M1067 235H1180')}${arrow('M1265 235H1330V295')}${node(8,'Digital IF output',text(1295,325,'Sampled IF',14)+text(1295,348,'9.548 MHz',14))}
 <g fill="none" stroke="#ffd17a" stroke-width="3"><circle cx="190" cy="530" r="27"/><path d="M171 530q9 -24 19 0t19 0"/><rect x="320" y="503" width="210" height="54" rx="6"/><rect x="920" y="503" width="110" height="54" rx="6"/><path d="M530 530H580"/><circle cx="580" cy="530" r="4" fill="#ffd17a"/></g>${text(90,575,'Reference clock',14)}${text(190,598,'10 MHz',15,'#ffd17a')}${text(425,535,'Frequency synthesizer',16)}${text(425,585,'1527.68 MHz',15,'#ffd17a')}${text(975,539,'&#247; 40',24)}${text(1110,585,'38.192 MHz sampling clock',15,'#ffd17a')}${arrow('M217 530H320',true)}${text(670,382,'LO: 1527.68 MHz',13,'#ffd17a')}${arrow('M580 530V262',true)}${arrow('M580 530H920',true)}${arrow('M1030 530H1222V265',true)}</svg></div><p class="fe-system-note">The two synthesizer branches share the same output: 1527.68 MHz to the mixer; 1527.68 / 40 = 38.192 MHz to the ADC. Analog IF: 1575.42 &#8722; 1527.68 = 47.74 MHz. Sampling places the real digital IF at 47.74 &#8722; 38.192 = 9.548 MHz. Sampling and quantization occur in the ADC.</p><p class="fe-system-note">Minimum bandwidth in the diagram refers to the 2.046 MHz GPS L1 C/A null-to-null main lobe. The simulated reference hardware uses 50 MHz RF, 18 MHz first IF and 6 MHz final IF filters; these values are unchanged.</p><p class="fe-book-reference"><strong>Reference architecture:</strong> teaching adaptation of Borre, K., Akos, D. M., Bertelsen, N., Rinder, P., and Jensen, S. H. (2007). <cite>A Software-Defined GPS and Galileo Receiver: A Single-Frequency Approach</cite>. Birkh&#228;user Boston. Chapter 4, Figure 4.2, p. 55. <a href="https://doi.org/10.1007/978-0-8176-4540-3" target="_blank" rel="noopener">Book DOI &#8599;</a>. The minimum-bandwidth annotations follow the supplied updated teaching diagram.</p>`;
}
function persistContext(){GPS_L1_RECEIVED.saveContext({epoch:state.epoch,satellite:state.satellite,source:state.source,includeNoise:state.includeNoise,view:state.receivedView==='delay'?'delay':state.source==='individual'?'received':'scene'});}
function context(){
 const m=state.path?.models[state.path.satellites.indexOf(state.satellite)],module=state.source==='mixed'?'08: All-Satellite Receiver':'09: Individual Received Signal';
 return card('Received GPS L1 C/A Signal',`<div class="fe-prose"><p id="signal-source-summary"><strong>Source: GNSS Signal Simulation &middot; Module ${module}.</strong> ${state.includeNoise?'The same modeled receiver-noise realization is retained.':'Noise is disabled for an idealized comparison.'}</p><p><a href="/signals/#scene">View Module 08</a> &middot; <a href="/signals/#received">View Module 09</a> &middot; <a href="/signals/#delay">Doppler and code delay</a> &middot; <a href="/signals/#navrx">Navigation at the receiver</a></p></div>${m?`<div class="fe-values"><div><span>Selected GPS satellite</span><strong>${esc(state.satellite)}</strong><small>GPS L1 C/A &middot; 1575.42 MHz</small></div><div><span>${FE_CONCEPTS.text('Observed Doppler')}</span><strong>${m.doppler.toFixed(2)} Hz</strong><small>RINEX D observable</small></div><div><span>${FE_CONCEPTS.text('Code delay modulo C/A period')}</span><strong>${m.delayChips.toFixed(3)} chips</strong><small>${FE_CONCEPTS.text('C/N₀')} ${m.cn0.toFixed(1)} ${FE_CONCEPTS.text('dB-Hz')}</small></div></div>`:''}<details class="fe-worked"><summary>Satellite, observation epoch and signal representation</summary><div class="fe-controls"><label>Observation epoch index<input id="fe-epoch" type="number" min="0" max="${Math.max(0,(state.meta?.dataset.epoch_count||1)-1)}" value="${state.epoch}" ${state.meta?'':'disabled'}></label><label>GPS satellite<select id="fe-satellite" ${state.path?'':'disabled'}>${state.scene.map(c=>`<option ${c.satellite===state.satellite?'selected':''}>${esc(c.satellite)}</option>`).join('')}</select></label><label>Signal illustration<select id="fe-source"><option value="mixed">Composite GPS L1 C/A signal</option><option value="individual">Selected satellite contribution</option></select></label><label>Receiver noise<select id="fe-noise" ${state.path?'':'disabled'}><option value="noisy">Include modeled receiver noise</option><option value="ideal">Idealized no-noise comparison</option></select></label></div></details><div class="fe-note" id="fe-context" data-satellite="${esc(state.satellite||'')}" data-epoch-index="${state.epoch}" data-source="${state.source}">${state.path?`${esc(state.satellite)} &middot; ${esc(state.path.epoch)} &middot; ${state.scene.length} complete GPS L1 C/A channels; ${state.omitted||0} omitted for incomplete observations. ${state.selectionNotice||''}`:'Loading the same received-signal context used in GNSS Signal Simulation. The source-based lecture remains available.'}</div>`);
}
function signalPanels(){return card('Signal Transformation: Input and Output',`<div class="fe-handoff"><div><b id="block-input-label">Input signal</b><span id="block-input-state">From the preceding receiver block.</span></div><i aria-hidden="true">&#8594;</i><div><b>${curriculum[state.lesson].title}</b><span>The selected satellite and epoch remain fixed.</span></div><i aria-hidden="true">&#8594;</i><div><b id="block-output-label">Output signal</b><span id="block-output-state">Passed to the next receiver block.</span></div></div><div class="fe-prose"><h4>Input to This Section</h4></div><div class="fe-two"><div><div class="fe-prose"><h4>Time-Domain Representation</h4></div><div class="fe-plot" id="input-wave"></div></div><div><div class="fe-prose"><h4>Frequency-Domain Representation</h4></div><div class="fe-plot" id="input-spectrum"></div></div></div><div class="fe-prose"><h4>Output from This Section</h4></div><div class="fe-two"><div><div class="fe-prose"><h4>Time-Domain Representation</h4></div><div class="fe-plot" id="stage-wave"></div></div><div><div class="fe-prose"><h4>Frequency-Domain Representation</h4></div><div class="fe-plot" id="stage-spectrum"></div></div></div><div class="fe-note" id="stage-description">Preparing the received-signal illustration.</div>`);}

function spectrumContext(){
 const t=(x,y,label,size=14,color='#b9cede',anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${color}" font-size="${size}">${label}</text>`;
 const x=f=>f<=1300?190+(f-1160)*3.65:800+(f-1550)*3.65;
 const bands=[[1164,1215,'#28516b'],[1215,1300,'#384968'],[1559,1610,'#28516b']];
 const lanes=[['GPS',300,'#ffd17a',[['L5',1176.45],['L2',1227.60],['L1 C/A',1575.42]]],['Galileo',390,'#89b5ff',[['E5a',1176.45],['E5b',1207.14],['E6',1278.75],['E1',1575.42]]],['GLONASS',480,'#ff9c86',[['G3',1202.025],['G2*',1246],['G1*',1602]]]];
 return card('Electromagnetic Spectrum and GNSS Frequency Bands',`<div class="fe-frequency-intro"><div><span class="eyebrow">FROM THE SPECTRUM TO GPS L1</span><p>GNSS uses radio waves in the microwave region. The L-band spans 1&#8211;2 GHz; GPS L1 C/A is centred at <strong>1575.42 MHz</strong>, with a wavelength of approximately <strong>19.03 cm</strong>.</p></div></div><div class="fe-reference-scroll" tabindex="0" role="region" aria-label="GNSS frequency bands; scroll horizontally on a small screen"><svg class="fe-spectrum-svg" viewBox="0 0 1100 620" role="img" aria-labelledby="frequency-chart-title frequency-chart-desc"><title id="frequency-chart-title">GNSS frequency regions and carrier positions</title><desc id="frequency-chart-desc">An independently drawn, split frequency axis compares GPS, Galileo and GLONASS carriers. Shaded regions show RNSS bands. Carrier markers do not represent occupied signal bandwidth. GPS L1 C/A at 1575.42 MHz is highlighted.</desc><rect x="20" y="16" width="1060" height="585" rx="14" fill="#0c1c2d"/>${t(40,51,'GNSS frequency regions',20,'#e4eef8','start')}${t(440,95,'Lower L-band',16)}${t(925,95,'Upper L-band',16)}${bands.map(([lo,hi,c])=>`<rect x="${x(lo)}" y="114" width="${x(hi)-x(lo)}" height="42" rx="5" fill="${c}"/>${t((x(lo)+x(hi))/2,140,lo+'&#8211;'+hi+' MHz',12,'#e4eef8')}`).join('')}${t(155,141,'RNSS',12,'#9ec4d9','end')}<rect x="${x(1575.42)-40}" y="166" width="80" height="350" rx="10" fill="#72d8ef" fill-opacity=".08" stroke="#72d8ef" stroke-opacity=".45"/>${t(x(1575.42),191,'GPS L1',12,'#72d8ef')}${[1160,1180,1200,1220,1240,1260,1280,1300,1560,1580,1600,1610].map(f=>`<path d="M${x(f)} 207V532" stroke="#2b4156" stroke-dasharray="3 6"/>${t(x(f),555,String(f),12)}`).join('')}<path d="M190 532H701M800 532H1050" stroke="#65839a"/><path d="M746 520l-8 23m21 -23l-8 23" stroke="#a7c4d5" stroke-width="2"/>${lanes.map(([name,y,color,signals])=>`${t(45,y-5,name,16,color,'start')}<path d="M190 ${y}H701M800 ${y}H1050" stroke="#294258"/>${signals.map(([name,f])=>{const px=x(f),focus=name==='L1 C/A';return `<rect x="${px-5}" y="${y-9}" width="10" height="18" rx="3" fill="${focus?'#72d8ef':color}"/>${t(px,y-24,name,14,focus?'#72d8ef':color)}${t(px,y+28,f.toFixed(f===1202.025?3:2),12,'#c5d8e7')}`;}).join('')}`).join('')}${t(590,589,'Frequency (MHz) / axis break omits 1300-1550 MHz',13)}</svg></div><div class="fe-band-notes"><p><strong>Read the chart:</strong> shaded areas identify radionavigation-satellite service (RNSS) frequency regions. Narrow markers locate carriers; their width does not show the transmitted signal bandwidth.</p><p><strong>GPS L1 C/A:</strong> the carrier is 1575.42 MHz; the main-lobe edges are 1574.397 and 1576.443 MHz. Their separation is 2.046 MHz.</p><p><strong>* GLONASS:</strong> G1 and G2 show channel k = 0. Actual carriers are 1602 + 0.5625k MHz and 1246 + 0.4375k MHz. Other constellations provide context; this laboratory processes GPS L1 C/A only.</p></div><p class="fe-spectrum-caption">Original NVGL chart. Carrier frequencies and allocated regions are distinct from signal bandwidths. Galileo frequency values follow the Galileo Open Service Signal-in-Space Interface Control Document.</p>`);
}
function supportContent(){const n=state.lesson;
 if(n===0)return card('Illustrative Carrier and Code Modulation',`<div class="fe-controls"><label>Carrier phase <output id="fe-carrier-phase-value">${state.carrierPhase} degrees</output><input id="fe-carrier-phase" type="range" min="0" max="360" step="5" value="${state.carrierPhase}"></label></div>`+prose('Move the phase slider to see how phase shifts the carrier. The code reverses its sign by 180 degrees. Carrier frequency is reduced for visual clarity; these diagrams are idealized voltage waves, not recorded receiver signals.')+`<div class="fe-two"><div id="ideal-carrier" class="fe-plot"></div><div id="ideal-bpsk" class="fe-plot"></div></div><div id="main-lobe" class="fe-plot"></div>`);
 if(n===1)return card('Reference Design Parameters',`<div class="fe-table-wrap"><table><thead><tr><th>Quantity</th><th>Reference value</th></tr></thead><tbody>${[['GPS L1 RF carrier','1575.42 MHz'],['Receiver reference clock','10 MHz'],['Local oscillator','1527.68 MHz'],['Analog IF','47.74 MHz'],['Sampling frequency','38.192 MHz'],['Digital IF','9.548 MHz'],['ADC resolution','4 bits; 16 quantization levels']].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div>`);
 if(n===2)return FE_POLARIZATION.render();
 if(n===3)return FE_FILTER_VISUAL.render(3);
 if(n===4)return card('Amplification and Signal-to-Noise Ratio',`<div class="fe-controls"><label>Gain sensitivity experiment <output id="fe-amplifier-gain-value">${state.experimentGain} dB</output><input id="fe-amplifier-gain" type="range" min="0" max="40" step="1" value="${state.experimentGain}"></label></div><div class="fe-prose"><p id="fe-amplifier-result"></p><p>The experiment compares a chosen gain with the fixed 20 dB reference path; it does not alter the signal used in later stages.</p></div>`+prose('The same analog waveform and existing noise are amplified together. The 20 dB illustration multiplies voltage by ten at unchanged impedance. The reference IF amplifier is a separate 50 dB stage.')+`<div id="amplifier-before-after" class="fe-plot"></div><div class="fe-equation">Fsystem = F1 + (F2 - 1)/G1 + (F3 - 1)/(G1 G2) + ...</div>`+prose('F denotes linear noise factor; G denotes linear power gain. Noise figure in dB is 10 log10(F). Placing substantial cable loss before the first LNA degrades receiver sensitivity.'));
 if(n===5)return '';
 if(n===6)return FE_FILTER_VISUAL.render(6);
 if(n===7)return card('Sampling Instants and Quantization Levels',prose('Sampling chooses when to measure voltage. Quantization chooses which numerical level represents each measurement. These idealized diagrams isolate the two operations; the signal-transformation plots below use the selected received GPS signal.')+`<div id="sampling-points" class="fe-plot"></div><div id="quantization-bins" class="fe-plot"></div>`);
 if(n===8)return card('Three Representations of the Same Digital Signal',prose('Time domain: sample amplitudes and clipping. Histogram: occupancy of the 16 quantization levels. Frequency domain: sampled spectral content. These are three views of one sample sequence, not three different output signals.')+digitalControls()+digitalPanels());
 return card('Complete Signal Transformation',`<div class="fe-table-wrap"><table><thead><tr><th>Front-end operation</th><th>Time-domain condition</th><th>Frequency-domain condition</th></tr></thead><tbody>${[['Receiving antenna','Weak analog noise-like voltage','L1 centered at 1575.42 MHz'],['RF bandpass filter','Analog; reduced unwanted energy','50 MHz RF passband'],['RF amplifier','Larger analog signal and noise','Center unchanged'],['Mixer','Analog frequency-converted voltage','47.74 MHz difference and 3103.10 MHz sum'],['First IF filter','Analog; unwanted products reduced','Approximately 18 MHz passband'],['IF amplifier','Increased analog IF amplitude','Approximately 50 dB gain'],['Final IF filter','Band-limited analog voltage','Approximately 6 MHz around 47.74 MHz'],['ADC sampling','Measurements at discrete instants','IF aliases to 9.548 MHz'],['ADC quantization','16 finite amplitude levels','Digital IF with quantization effects'],['Digital output','Noise-like numerical samples','Desired modulation retained']].map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
}
function digitalControls(){return `<div class="fe-controls"><label>ADC input gain <output id="adc-gain-value">${state.gain.toFixed(1)} times</output><input id="adc-gain" type="range" min="0.1" max="3" step="0.1" value="${state.gain}"></label><span class="fe-control-note">Compare low gain, normal range utilization and clipping. The gain control changes the same samples in all three plots.</span></div>`;}
function digitalPanels(){return `<div class="fe-three"><div id="digital-time" class="fe-plot"></div><div id="digital-histogram" class="fe-plot"></div><div id="digital-spectrum" class="fe-plot"></div></div><div id="digital-description" class="fe-note"></div>`;}
function render(){
 FE_POLARIZATION.stop();FE_CHARTS.reset($('front-end-main'));sourceDemand.disconnect();
 const i=state.lesson,l=FE_LESSONS[i],course=curriculum[i];FE_CONCEPTS.setSection(i);$('front-end-main').setAttribute('aria-labelledby','fe-topic-'+i);
 $('fe-nav').innerHTML=shortTitles.map((title,n)=>`<button type="button" role="tab" id="fe-topic-${n}" aria-controls="front-end-main" aria-selected="${i===n}" tabindex="${i===n?0:-1}" class="${i===n?'active':''}" style="--stage-accent:${colors[n]}" data-lesson="${n}">${title}</button>`).join('');
 requestAnimationFrame(()=>{const nav=$('fe-nav'),active=nav.querySelector('[aria-selected="true"]');if(active){const left=active.getBoundingClientRect().left-nav.getBoundingClientRect().left+nav.scrollLeft;if(left<nav.scrollLeft)nav.scrollLeft=left-10;else if(left+active.offsetWidth>nav.scrollLeft+nav.clientWidth)nav.scrollLeft=left+active.offsetWidth-nav.clientWidth+10;}updateTopicArrows();});
 $('front-end-main').innerHTML=`<section class="fe-lesson active" style="--fe-stage-color:${colors[i]}"><div class="section-head"><span class="eyebrow">GNSS FRONT END</span><h2>${course.title}</h2><div class="fe-introduction"><span class="fe-introduction-label">Definition</span><p>${FE_CONCEPTS.text(course.definition||l.definition)}</p></div><p class="fe-learning-focus">${course.focus}</p><a class="fe-prerequisite-link" id="fe-foundation-link" href="#fe-foundations">Review electrical fundamentals and units &#8594;</a></div><nav class="fe-reading-nav" aria-label="Navigate this lesson"><a href="#front-end-main">Overview</a><a href="#fe-received-lab" data-received-lab-link>Received signal</a><a href="#fe-system-overview">Diagram</a><a href="#fe-definitions-title">Definitions</a><a href="#fe-experiment">Experiment</a><a href="#fe-signal-transformation">Signal</a><a href="#fe-worked-example">Example</a><button type="button" id="fe-reading-prev" aria-label="Previous topic" ${i===0?'disabled':''}>&#8592;</button><button type="button" id="fe-reading-next" aria-label="Next topic">&#8594;</button></nav>${activityGuide(i)}${state.engineFailed?'<p class="fe-source-error" role="status">The recorded signal could not load. Concept experiments remain available. <button type="button" id="fe-science-retry">Retry recorded signal</button></p>':''}${i===0?FE_PRINCIPLES.render(0)+spectrumContext():i===1?FE_RECEIVED_LAB.render(state):''}<section id="fe-system-overview" class="fe-system-overview" aria-label="Receiver diagram for the current section">${architecture()}</section>${i===0?'<p class="fe-simulation-continuity">This lesson continues the received GPS L1 C/A signal from <a href="/signals/#received">GNSS Signal Simulation, Module 09</a>. Use <a href="/signals/#scene">Module 08</a> for the all-satellite mixture. The selected satellite and epoch are retained.</p>':''}<details class="fe-worked fe-concept-reference"><summary>Concept definitions for this topic</summary><div class="fe-worked-body">${FE_CONCEPTS.render(i)}</div></details>${i===4?FE_FOUNDATIONS.render(i).replace(/id="fe-foundations"\s+open/,'id="fe-foundations"'):''}${![0,1,5,7].includes(i)?card(['','','Reception: From Field to Voltage','Frequency Selection and Out-of-Band Rejection','Power Gain and Receiver Noise','','Band Limiting Before the ADC','','Reading a Digital Sample Sequence','From Digital IF to Raw Sample Files'][i],prose(course.explanation||l.change)):''}${i!==0?FE_PRINCIPLES.render(i):''}${supportContent()}<details class="fe-worked fe-source-reference"><summary>Shared Signal Source and Observation Controls</summary><div class="fe-worked-body">${context()}</div></details>${i!==0&&i!==8?signalPanels():''}${card('Worked Example',(i===4?'<div class="fe-equation">Pout(dBm) = Pin(dBm) + G(dB) = -130 + 20 = -110 dBm</div>':FE_LECTURE_VIEW.exampleMath(i))+prose(course.example||l.example)+FE_CONCEPTS.mathHelp(i))}<details class="fe-worked fe-reference-library"><summary>Source Lecture and Further Reading</summary><div class="fe-worked-body">${FE_LECTURE_VIEW.topics(i)}</div></details>${i===9?`<details class="fe-worked" id="iq-supplement" open><summary>Raw I/Q Files, Phase Preservation and Software Receivers</summary><div class="fe-worked-body"><p>The reference front end produces real four-bit digital IF. A further digital downconversion can form complex baseband I/Q. The two file representations must be distinguished.</p>${rawContent()}</div></details>`:''}${i===9?FE_LECTURE_VIEW.glossary(i,true):''}<div class="fe-next"><a href="/signals">GNSS Signal Simulation</a><a id="fe-prev" href="#front-end-main">Previous topic</a><a class="fe-primary" id="fe-next" href="#front-end-main">${i===9?'Return to Spectrum':'Next topic'}</a></div></section>`;
 document.querySelectorAll('.fe-lesson>.fe-card').forEach(panel=>{const title=panel.querySelector('h3')?.textContent;if(title==='Signal Transformation: Input and Output'||title==='Three Representations of the Same Digital Signal'||title==='Illustrative Carrier and Code Modulation')panel.id='fe-signal-transformation';if(title==='Worked Example')panel.id='fe-worked-example';});
 $('fe-reading-prev').onclick=()=>go(Math.max(0,i-1));$('fe-reading-next').onclick=()=>go((i+1)%10);
 document.querySelectorAll('.fe-reading-nav a').forEach(link=>link.onclick=event=>{if(link.hasAttribute('data-received-lab-link')&&state.lesson!==1){event.preventDefault();go(1);$('fe-received-lab').scrollIntoView({block:'start'});return;}const target=document.querySelector(link.getAttribute('href'));if(!target)return;event.preventDefault();for(let node=target.parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
 document.querySelectorAll('[data-section]').forEach(button=>button.onclick=()=>go(Number(button.dataset.section)));
 document.querySelectorAll('[data-chain-section]').forEach(link=>link.onclick=event=>{event.preventDefault();go(Number(link.dataset.chainSection));});
 $('fe-prev').onclick=event=>{event.preventDefault();go(Math.max(0,i-1));};$('fe-next').onclick=event=>{event.preventDefault();go((i+1)%10);};
 $('fe-epoch').onchange=event=>selectEpoch(Number(event.target.value));
 $('fe-satellite').onchange=event=>{if(!state.scene.some(channel=>channel.satellite===event.target.value))return;state.satellite=event.target.value;rebuild();render();};$('fe-source').value=state.source;$('fe-source').onchange=event=>{state.source=event.target.value;state.receivedView=state.source==='mixed'?'all':'individual';persistContext();render();};$('fe-noise').value=state.includeNoise?'noisy':'ideal';$('fe-noise').onchange=event=>{state.includeNoise=event.target.value==='noisy';if(state.scene.length&&state.satellite)rebuild();render();};
 FE_LECTURE_VIEW.bind();FE_FOUNDATIONS.bind();FE_CONCEPTS.bind();FE_PRINCIPLES.bind(i);FE_FILTER_VISUAL.bind(state,plot);if(i===2)FE_POLARIZATION.bind();
 if(i===1)FE_RECEIVED_LAB.bind(state,{view:value=>{if(state.receivedView===value)return;state.receivedView=value;state.source=value==='all'?'mixed':'individual';persistContext();render();},satellite:value=>{if(state.satellite===value)return;state.satellite=value;rebuild();render();},epoch:selectEpoch,noise:value=>{if(state.includeNoise===value)return;state.includeNoise=value;rebuild();render();},follow:()=>{go(2);}});
 if(i!==4)$('fe-foundation-link').onclick=event=>{event.preventDefault();go(4);$('fe-foundations').open=true;$('fe-foundations').scrollIntoView({block:'start'});};
 if($('fe-carrier-phase'))$('fe-carrier-phase').oninput=event=>{state.carrierPhase=Number(event.target.value);$('fe-carrier-phase-value').textContent=state.carrierPhase+' degrees';drawSupport();};
 if($('fe-amplifier-gain'))$('fe-amplifier-gain').oninput=event=>{state.experimentGain=Number(event.target.value);$('fe-amplifier-gain-value').textContent=state.experimentGain+' dB';drawSupport();};
 if($('adc-gain'))$('adc-gain').oninput=event=>{state.gain=Number(event.target.value);$('adc-gain-value').textContent=state.gain.toFixed(1)+' times';drawDigital();};
 document.querySelectorAll('.fe-source-reference').forEach(panel=>panel.ontoggle=()=>{if(panel.open)ensureScientificEngine();});
 if($('iq-supplement'))$('iq-supplement').ontoggle=()=>{if($('iq-supplement').open){$('phase').oninput=drawPhase;drawPhase();$('download-iq').onclick=async()=>{await ensureScientificEngine();if(state.path)download(state.path[state.source][7].bytes,'gps_l1_ca_model.cu8','application/octet-stream');};$('download-meta').onclick=async()=>{await ensureScientificEngine();if(state.path)download(JSON.stringify({satellite:state.satellite,epoch:state.path.epoch,sample_rate:state.path.fs,center_frequency:1575420000,format:'CU8',order:'I0 Q0 I1 Q1',pairs:4096,source:'Observation-anchored supplementary reconstruction, not recorded RF'},null,2),'gps_l1_ca_model.json','application/json');};}};
 bindActivity(i);
 watchScientificSources(i);
 if($('fe-science-retry'))$('fe-science-retry').onclick=()=>{state.engineFailed=false;state.sceneError='';enginePromise=null;ensureScientificEngine();};
 requestAnimationFrame(drawArchitectureConnections);
 drawAll();
}
function go(index){state.lesson=index;render();const heading=document.querySelector('.section-head h2');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});document.querySelector('.fe-lesson').scrollIntoView({block:'start',behavior:'instant'});}
function spectrum(s){let result=spectra.get(s);if(!result){result=FRONT_END_PATH.fftSpectrum(s.I,s.Q,s.fs);spectra.set(s,result);}return result;}
function drawAll(){
 if(state.lesson===1)FE_RECEIVED_LAB.draw(state,plot);drawSupport();if(state.lesson===0||!state.path)return;if(state.lesson===8){drawDigital();return;}
 const index=FE_LESSONS[state.lesson].stage,inputIndex=state.lesson===9?0:Math.max(0,index-1),path=state.path[state.source],output=state.lesson===5?path[4].first:path[index],input=state.lesson===6?path[4].first:path[inputIndex];
 const names=['Received antenna-terminal voltage','RF filter output','RF amplifier output','Mixer difference-frequency output','Conditioned analog IF','ADC output','Digital IF output'];
 function draw(stage,waveId,spectrumId,color){
  const duration=GPS_L1_RECEIVED.DISPLAY_SAMPLES/GPS_L1_RECEIVED.MODEL_RATE,n=Math.min(stage.I.length,Math.round(duration*stage.fs)),t=Array.from({length:n},(_,i)=>i/stage.fs*1e6),voltage=stage.analog?(stage.voltage||stage.I):stage.I;
  const timeTrace=trace(t,voltage.slice(0,n),stage.analog?'Analog voltage illustration':'Four-bit digital samples',color);
  if(!stage.analog){timeTrace.mode='lines+markers';timeTrace.line.shape='hv';timeTrace.marker={size:3};}
  plot(waveId,[timeTrace],'Time (microseconds)',stage.analog?'Analog voltage / envelope (relative units)':'Quantized amplitude (relative units)');
  const spec=spectrum(stage),indices=spec.f.map((_,i)=>i).filter(i=>stage.analog||spec.f[i]>=0);
  plot(spectrumId,[trace(indices.map(i=>(spec.f[i]+stage.center)/1e6),indices.map(i=>spec.p[i]),stage.analog?'Analog spectral illustration':'Digital IF spectrum',color)],'Frequency (MHz)','Relative power per frequency bin (dB)');
 }
 draw(input,'input-wave','input-spectrum','#b8cbdc');draw(output,'stage-wave','stage-spectrum',colors[state.lesson]);
 // Equal vertical scales make gain and limiting visible rather than autoscaling them away.
 const amplitude=Math.max(...input.I.map(Math.abs),...output.I.map(Math.abs),...(input.voltage||[]).map(Math.abs),...(output.voltage||[]).map(Math.abs))*1.05;
 FE_CHARTS.relayout('input-wave',{'yaxis.range':[-amplitude,amplitude]});FE_CHARTS.relayout('stage-wave',{'yaxis.range':[-amplitude,amplitude]});const powers=spectrum(input).p.concat(spectrum(output).p),powerRange=[Math.min(...powers)-3,Math.max(...powers)+3];FE_CHARTS.relayout('input-spectrum',{'yaxis.range':powerRange});FE_CHARTS.relayout('stage-spectrum',{'yaxis.range':powerRange});
 $('block-input-label').textContent=state.lesson===6?'First IF filter output':names[inputIndex];$('block-output-label').textContent=state.lesson===5?'Downconversion output: first filtered IF':names[index];
 const describe=stage=>`${stage.analog?'Analog':'Digital'}; carrier / IF center ${(stage.analog?stage.center:9.548e6)/1e6} MHz. ${stage.analog?'No ADC sampling has occurred.':'38.192 million samples/s; 16 quantization levels.'}`;
 $('block-input-state').textContent=describe(input);$('block-output-state').textContent=describe(output);
 const unchanged=index===inputIndex?'This section examines the same received reference signal; no additional conditioning is applied. ':index===6&&inputIndex===5?'The digital output reuses the ADC sample sequence; this section changes its representation, not its values. ':'';
 $('stage-description').textContent=unchanged+`The input and output use ${state.satellite} at ${state.path.epoch}, with the same observed code delay, Doppler, carrier phase and ${state.includeNoise?'receiver-noise realization':'idealized noise-free source'}. The horizontal axis retains the same observation-time origin; filter processing delay is preserved. `+(output.analog?'The signal remains analog. RF waveforms are voltage-envelope illustrations, not an ADC or raw I/Q file.':'Sampling and quantization occur only at the ADC. Digital samples retain the received GPS modulation.')+' These are observation-anchored reconstructions from GNSS Signal Simulation, not captured RF recordings.';
 if(state.lesson>=7&&state.lesson<=8)drawDigital();
}

function drawSupport(){
 const i=state.lesson;
 if(i===0){
  const phase=state.carrierPhase*Math.PI/180,t=Array.from({length:601},(_,n)=>3*n/600),m=state.path?.models[state.path.satellites.indexOf(state.satellite)],chips=m?[0,1,2].map(n=>RECEIVER_MODEL.codeSign(m,n/m.codeRate)):[1,-1,1],sine=t.map(x=>Math.sin(2*Math.PI*x+phase)),modulated=t.map(x=>Math.sin(2*Math.PI*4*x+phase)*chips[Math.min(2,Math.floor(x))]);
  plot('ideal-carrier',[trace(t,sine,'One cycle per unit time')],'Illustrative time (arbitrary units)','Carrier amplitude');
  plot('ideal-bpsk',[trace(t,modulated,'Code signs '+chips.join(', '))],'Three illustrative chip intervals','Modulated carrier amplitude');
  const f=Array.from({length:801},(_,n)=>1575.42+(n-400)*.01),p=f.map(x=>{const u=(x-1575.42)/1.023,v=u===0?1:Math.sin(Math.PI*u)/(Math.PI*u);return 10*Math.log10(Math.max(1e-8,v*v));});
  plot('main-lobe',[trace(f,p,'Rectangular-chip power-spectrum envelope')],'Frequency (MHz)','Normalized power (dB)',{shapes:[1574.397,1576.443].map(x=>({type:'line',x0:x,x1:x,y0:-80,y1:0,line:{color:'#b8cbdc',dash:'dot'}})),annotations:[{x:1575.42,y:0,text:'L1 1575.42 MHz; first-null width 2.046 MHz',showarrow:false,yshift:12}]});
 }

 if(i===4&&state.path){const a=state.path[state.source][1],b=state.path[state.source][2],t=Array.from({length:600},(_,n)=>n/a.fs*1e6);plot('amplifier-before-after',[trace(t,a.I.slice(0,600),'Input','#b8cbdc'),trace(t,b.I.slice(0,600),'Reference: 20 dB','#89b5ff'),trace(t,a.I.slice(0,600).map(v=>v*10**(state.experimentGain/20)),'Chosen experiment gain')],'Time (microseconds)','Analog voltage envelope (relative units)');$('fe-amplifier-result').textContent='For a stated -130 dBm input, '+state.experimentGain+' dB gain gives '+(-130+state.experimentGain)+' dBm output. Equal-impedance voltage factor: '+(10**(state.experimentGain/20)).toFixed(2)+'. Signal and existing noise are amplified together.';}
 if(i===5)plot('mixer-products',[{x:[47.74,1479.94,1527.68,1575.42,3103.10],y:[1,0.5,.7,.8,1],text:['Desired difference','RF image','Local oscillator','Desired RF input','Unwanted sum'],type:'scatter',mode:'markers+text',textposition:'top center',marker:{size:12,color:['#6ce0bc','#b8cbdc','#bea6ff','#72d8ef','#ff9c86']},name:'Frequency locations'}],'Frequency (MHz)','Schematic component markers (not measured power)',{margin:{l:60,r:60,t:70,b:70}});

 if(i===7){const dense=Array.from({length:801},(_,n)=>n*.4/800),sample=Array.from({length:16},(_,n)=>n/38.192);plot('sampling-points',[trace(dense,dense.map(t=>Math.cos(2*Math.PI*47.74*t)),'Ideal analog IF sinusoid'),{...trace(sample,sample.map(t=>Math.cos(2*Math.PI*47.74*t)),'Sampling instants','#ffd17a'),mode:'markers',marker:{size:7}}],'Illustrative time (microseconds)','Normalized analog voltage');plot('quantization-bins',[{x:Array.from({length:16},(_,n)=>n),y:new Array(16).fill(1),width:new Array(16).fill(.94),type:'bar',name:'Equal-width bins',marker:{color:colors[i]}}],'Four-bit quantization code (0-15)','Uniform normalized bin width',{yaxis:{visible:false},annotations:[{x:7.5,y:1.12,text:'16 equal-width bins across the ADC input range',showarrow:false}],margin:{l:35,r:20,t:60,b:65}});}
}
function drawDigital(){if(!state.path||!$('digital-time'))return;const source=state.path[state.source][5],range=state.path.fullScale,step=range/8,input=source.input.map(v=>v*state.gain),codes=input.map(v=>Math.max(0,Math.min(15,Math.floor((v/range+1)*8)))),values=codes.map(code=>-range+(code+.5)*step),counts=new Array(16).fill(0);for(const code of codes)counts[code]++;const n=1000,t=Array.from({length:n},(_,k)=>k/source.fs*1e6),timeTrace=trace(t,values.slice(0,n),'Digital IF samples');timeTrace.mode='lines+markers';timeTrace.line.shape='hv';timeTrace.marker={size:2};plot('digital-time',[timeTrace],'Time (microseconds)','Quantized amplitude');plot('digital-histogram',[{x:Array.from({length:16},(_,n)=>n),y:counts,type:'bar',marker:{color:colors[state.lesson]},name:'Sample count'}],'Quantization code (0-15)','Number of samples');const spec=FRONT_END_PATH.fftSpectrum(values,new Array(values.length).fill(0),source.fs),half=spec.f.map((_,k)=>k).filter(k=>spec.f[k]>=0);plot('digital-spectrum',[trace(half.map(k=>spec.f[k]/1e6),half.map(k=>spec.p[k]),'Same-sequence spectrum')],'Digital frequency (MHz)','Relative power per frequency bin (dB)');const clipped=input.filter(v=>v< -range||v>=range).length;$('digital-description').textContent=`Histogram total: ${counts.reduce((a,b)=>a+b,0).toLocaleString()} = ${codes.length.toLocaleString()} samples. All three plots use this same sample sequence. The time-domain panel shows the first 1,000 samples, spanning approximately 26.2 microseconds. Gain: ${state.gain.toFixed(1)} times; clipped input values: ${clipped}. The ADC has 16 codes; it does not identify satellites or remove thermal noise.`;}
function rebuild(){const entries=GPS_L1_RECEIVED.prepare(state.scene);state.path=FRONT_END_PATH.build(entries,state.satellite,4096,{includeNoise:state.includeNoise});persistContext();}
async function json(url){const r=await fetch(url);if(!r.ok)throw Error(`${url}: ${r.status}`);return r.json();}
function selectEpoch(value){
 if(!state.meta||!Number.isInteger(value)||value<0||value>=state.meta.dataset.epoch_count||value===state.epoch)return;
 state.epoch=value;state.path=null;state.scene=[];state.sceneError='';render();loadScene();
}
async function loadScene(){const revision=++state.revision;try{const scene=await json(`/api/signals/scene?epoch=${state.epoch}`);if(revision!==state.revision)return;state.scene=scene.channels.filter(c=>GPS_L1_RECEIVED.complete(c));if(!state.scene.length)throw Error('This epoch has no complete GPS L1 C/A observations.');state.omitted=scene.channels.filter(c=>c.satellite.startsWith('G')&&c.signal.prn_mode==='gps-ca').length-state.scene.length;state.sceneError='';state.engineFailed=false;state.selectionNotice='';if(!state.scene.some(c=>c.satellite===state.satellite)){if(state.satellite)state.selectionNotice='The previous satellite is unavailable at this epoch; the first complete GPS channel is shown.';state.satellite=state.scene[0].satellite;}rebuild();render();}catch(error){if(revision===state.revision){state.sceneError=error.message;state.engineFailed=true;render();$('fe-context').textContent=error.message+' The source-based lecture remains available.';}}}
$('fe-nav').onclick=event=>{const button=event.target.closest('[data-lesson]');if(button)go(Number(button.dataset.lesson));};
$('fe-nav').onkeydown=event=>{const button=event.target.closest('[data-lesson]');if(!button)return;const index=Number(button.dataset.lesson);let next;if(event.key==='ArrowRight')next=(index+1)%10;else if(event.key==='ArrowLeft')next=(index+9)%10;else if(event.key==='Home')next=0;else if(event.key==='End')next=9;else return;event.preventDefault();go(next);$('fe-topic-'+next).focus({preventScroll:true});};
function updateTopicArrows(){const nav=$('fe-nav');$('fe-topics-left').disabled=nav.scrollLeft<=2;$('fe-topics-right').disabled=nav.scrollLeft+nav.clientWidth>=nav.scrollWidth-2;}
$('fe-nav').addEventListener('scroll',updateTopicArrows,{passive:true});window.addEventListener('resize',updateTopicArrows);
$('fe-topics-left').onclick=()=>$('fe-nav').scrollBy({left:-350,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('fe-topics-right').onclick=()=>$('fe-nav').scrollBy({left:350,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
const sourceDemand=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting))ensureScientificEngine();},{rootMargin:'240px 0px'});
let enginePromise=null;
function watchScientificSources(index){
 if(state.path||state.engineFailed)return;
 const selectors=index===0?[]:index===1?['#fe-received-lab']:index===3||index===6?['#fe-filter-lab']:index===4?['#amplifier-before-after','#fe-signal-transformation']:index===8?['#digital-time']:['#fe-signal-transformation'];
 for(const selector of selectors){const node=document.querySelector(selector);if(node)sourceDemand.observe(node);}
}
function ensureScientificEngine(){
 if(state.path)return Promise.resolve();if(enginePromise)return enginePromise;
 enginePromise=(async()=>{try{state.meta=state.meta||await json('/api/signals/meta');state.epoch=Math.max(0,Math.min(state.epoch,state.meta.dataset.epoch_count-1));await loadScene();}catch(error){state.sceneError=error.message;state.engineFailed=true;render();}})();return enginePromise;
}
(()=>{const saved=GPS_L1_RECEIVED.readContext();if(saved){state.epoch=saved.epoch;state.satellite=saved.satellite;state.source=saved.source==='individual'?'individual':'mixed';state.receivedView=saved.view==='delay'?'delay':state.source==='mixed'?'all':'individual';state.includeNoise=saved.includeNoise!==false;}render();})();


function rawContent(){return card('Reference Hardware, RTL-SDR, and GNSS-SDR',`<div class="fe-table-wrap"><table><thead><tr><th>System</th><th>Role and output</th></tr></thead><tbody><tr><td>Textbook reference front end</td><td>Analog IF 47.74 MHz; real sampling at 38.192 MHz; digital IF 9.548 MHz; four-bit ADC. File packing must be specified separately.</td></tr><tr><td>RTL-SDR hardware and rtl_sdr</td><td>RF tuner and quadrature digitizer; rtl_sdr writes unsigned interleaved I,Q bytes (CU8). The example capture uses 2.4 million complex pairs/s.</td></tr><tr><td>GNSS-SDR software</td><td>Accepts supported sample streams. This chapter covers file-source formats and the interface to recorded front-end samples.</td></tr></tbody></table></div>`)+card('Capture and File Interpretation',prose('CU8 order: I[0], Q[0], I[1], Q[1], ... . Each component is an unsigned byte with nominal midpoint 127.5. This convention differs from signed int8 interleaved samples. The same-rate I/Q teaching output above is 38.192 Mpairs/s; it is not an emulation of a 2.4 Msps RTL device.')+`<div class="fe-equation"><code>rtl_sdr -f 1575420000 -s 2400000 -g 40 -n 144000000 gps_l1_ca.cu8</code></div>`+prose('The count is 144,000,000 complex pairs, giving 60 seconds and 288,000,000 bytes. A supported L-band tuner, suitable GNSS antenna, adequate low-noise amplification and an appropriate gain setting are needed. The requested gain is mapped to a supported device gain. Actual hardware reception has not been tested here.')+`<div class="fe-controls"><button id="download-iq">Download current model CU8 block</button><button id="download-meta">Download matching metadata</button><a href="/reference/front_end/cu8_to_cf32.py" download>Download streaming CU8 converter</a></div>`)+card('GNSS-SDR File-Source Configuration',prose('Convert unsigned CU8 to little-endian complex float32 before using the gr_complex file source. The supplied streaming converter maps each byte b to (b - 127.5)/128. Do not label unsigned CU8 as ibyte: that GNSS-SDR format expects signed components.')+`<div class="fe-equation"><code>python cu8_to_cf32.py gps_l1_ca.cu8 gps_l1_ca.cf32</code><br><br><code>SignalSource.implementation=File_Signal_Source<br>SignalSource.filename=gps_l1_ca.cf32<br>SignalSource.item_type=gr_complex<br>SignalSource.sampling_frequency=2400000</code></div>`+prose('This is a source configuration fragment, not a complete receiver configuration. It specifies only the file interface. Complete software-receiver configuration is outside this chapter.')+`<div class="fe-equation"><code>gnss-sdr --config_file=gps_l1_ca.conf --signal_source=gps_l1_ca.cf32</code></div>`+prose('Command options and sample formats were checked against upstream RTL-SDR source and GNSS-SDR documentation. Neither receiver executable nor RF hardware has been run in this environment; hardware reception and processing of this capture are unverified. The short downloadable model block is for byte-format inspection, not a receiver qualification recording.'))+card('Phase Preservation in Quadrature Samples',prose('Hold one code chip and navigation symbol fixed, and remove nominal carrier rotation. At unit amplitude, I = cos(phi), Q = sin(phi). At 90 degrees the I-only baseband projection vanishes, while atan2(Q,I) still recovers phase. A properly sampled real IF also preserves phase; this experiment compares a single baseband projection with both quadratures.')+`<div class="fe-controls"><label>Carrier phase <output id="phase-value">90 degrees</output><input id="phase" type="range" min="0" max="360" step="1" value="90"></label></div><div class="fe-two"><div id="phase-wave" class="fe-plot"></div><div id="phase-circle" class="fe-plot"></div></div><div id="phase-result" class="fe-note" aria-live="polite"></div>`)+prose('References: <a href="https://github.com/osmocom/rtl-sdr/blob/master/src/rtl_sdr.c" target="_blank" rel="noopener">RTL-SDR capture source and option definitions</a>; <a href="https://gnss-sdr.org/docs/sp-blocks/signal-source/" target="_blank" rel="noopener">GNSS-SDR file source and command line</a>; <a href="https://github.com/gnss-sdr/gnss-sdr/blob/main/src/algorithms/signal_source/adapters/file_signal_source.cc" target="_blank" rel="noopener">GNSS-SDR file-source implementation</a>; <a href="https://gnss-sdr.org/docs/tutorials/understanding-data-types/" target="_blank" rel="noopener">GNSS-SDR data types</a>.');}
function drawPhase(){const degrees=Number($('phase').value),p=FRONT_END_PATH.phaseTest(degrees),x=Array.from({length:100},(_,i)=>i),a=Array.from({length:361},(_,i)=>i*Math.PI/180);$('phase-value').textContent=`${degrees} degrees`;plot('phase-wave',[trace(x,x.map(()=>p.I),'I-only projection'),trace(x,x.map(()=>p.Q),'Q projection','#6ce0bc'),trace(x,x.map(()=>Math.hypot(p.I,p.Q)),'I/Q magnitude','#ffd17a')],'Samples within a fixed chip and symbol','Amplitude');plot('phase-circle',[trace(a.map(Math.cos),a.map(Math.sin),'Unit phasor'),{x:[0,p.I],y:[0,p.Q],name:'Current I/Q',mode:'lines+markers',line:{color:'#6ce0bc'}}],'I','Q');$('phase-result').textContent=`I = ${p.I.toFixed(6)}, Q = ${p.Q.toFixed(6)}; atan2 phase = ${p.recoveredDegrees.toFixed(6)} degrees (modulo 360). Ideal wrapped phase error: ${p.errorDegrees.toExponential(1)} degrees. After unsigned 8-bit quantization: ${p.quantizedErrorDegrees.toFixed(4)} degrees. Both quadratures preserve ideal phase; finite bit depth and noise introduce error.`;}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
})();
